class ICD10ExtendedService:
    @staticmethod
    def get_diagnosis(code: str) -> Optional[ICD10ExtendedRecord]:
        return ICD10_EXTENDED_DATABASE.get(code.strip())

    @staticmethod
    def filter_by_specialty(specialty: str) -> List[ICD10ExtendedRecord]:
        return [d for d in ICD10_EXTENDED_DATABASE.values() if d.specialty.lower() == specialty.lower()][:100]
